#!/usr/bin/env python3
"""Host logic checks. Optional --cjson-dir points to a cJSON source checkout.
Without cJSON sources, parameter tests run and JSON controller tests are skipped.
Full firmware and hardware checks are listed in docs/TESTING.md.
"""
from pathlib import Path
import argparse
import os
import subprocess
import tempfile
ROOT = Path(__file__).resolve().parents[2]
STUBS = {'esp_heap_caps.h': '#pragma once\n#include <stdlib.h>\n#define MALLOC_CAP_SPIRAM 1\n#define MALLOC_CAP_8BIT 2\n#define MALLOC_CAP_INTERNAL 4\n#define heap_caps_calloc(n,s,c) calloc(n,s)\n#define heap_caps_malloc(s,c) malloc(s)\n#define heap_caps_realloc(p,s,c) realloc(p,s)\n#define heap_caps_free(p) free(p)\n', 'nvs.h': '#pragma once\n#include <stddef.h>\n#include "esp_err.h"\ntypedef int nvs_handle_t;\n#define NVS_READONLY 0\n#define NVS_READWRITE 1\nstatic inline esp_err_t nvs_open(const char *name,int mode,nvs_handle_t *handle){(void)name;(void)mode;(void)handle;return ESP_FAIL;}\nstatic inline esp_err_t nvs_get_blob(int h,const char *key,void *data,size_t *size){(void)h;(void)key;(void)data;(void)size;return ESP_FAIL;}\nstatic inline esp_err_t nvs_set_blob(int h,const char *key,const void *data,size_t size){(void)h;(void)key;(void)data;(void)size;return ESP_FAIL;}\nstatic inline esp_err_t nvs_commit(int h){(void)h;return ESP_OK;}\nstatic inline void nvs_close(int h){(void)h;}\n', 'esp_log.h': '#pragma once\n#define ESP_LOGI(...) ((void)TAG)\n#define ESP_LOGW(...) ((void)TAG)\n#define ESP_LOGE(...) ((void)TAG)\n', 'esp_timer.h': '#pragma once\n#include <stdint.h>\nint64_t esp_timer_get_time(void);\n', 'esp_err.h': '#pragma once\ntypedef int esp_err_t;\n#define ESP_OK 0\n#define ESP_FAIL 1\nconst char *esp_err_to_name(esp_err_t);\n', 'freertos/FreeRTOS.h': '#pragma once\ntypedef int portMUX_TYPE;\n#define portMUX_INITIALIZER_UNLOCKED 0\n#define portENTER_CRITICAL(lock) ((void)(lock))\n#define portEXIT_CRITICAL(lock) ((void)(lock))\n#define pdMS_TO_TICKS(x) (x)\n'}
TESTS = {'parameter': '#include <assert.h>\n#include <string.h>\n#include "macro_parameter_utils.h"\nint main(void) {\n macro_parameter_catalog_t out;\n macro_parameter_detect("{% set t=params.BED_TEMP|default(60) %} {params[\'EXTRUDER_TEMP\']} {params.get(\\"TOOL\\", 0)} {params.BED_TEMP} {rawparams.NOT_A_FIELD}", &out);\n assert(out.count==3 && !out.truncated);\n assert(!strcmp(out.names[0],"BED_TEMP") && !strcmp(out.names[1],"EXTRUDER_TEMP") && !strcmp(out.names[2],"TOOL"));\n macro_parameter_detect("params.A params.B params.C params.D params.E params.F params.G params.H params.I", &out);\n assert(out.count==8 && out.truncated);\n assert(macro_parameter_matches("START_PRINT", "print") && !macro_parameter_matches("PAUSE", "print"));\n macro_parameter_value_t values[]={{"BED_TEMP","60"},{"EXTRUDER_TEMP","205"},{"tool","0"},{"OPTIONAL",""}};\n char command[640];const char *error;\n assert(macro_parameter_build_command("START_PRINT",values,4,command,sizeof(command),&error));\n assert(!strcmp(command,"START_PRINT BED_TEMP=60 EXTRUDER_TEMP=205 TOOL=0"));\n values[0].value="foo bar.gcode";\n assert(macro_parameter_build_command("START_PRINT",values,1,command,sizeof(command),&error));\n assert(!strcmp(command,"START_PRINT BED_TEMP=\\"foo bar.gcode\\""));\n values[0].value="60\\nSAVE_CONFIG";\n assert(!macro_parameter_build_command("START_PRINT",values,1,command,sizeof(command),&error) && !command[0]);\n values[0].value="60;SAVE_CONFIG";assert(!macro_parameter_build_command("START_PRINT",values,1,command,sizeof(command),&error));\n values[0].value="60";values[1].name="bed_temp";\n assert(!macro_parameter_build_command("START_PRINT",values,2,command,sizeof(command),&error));\n assert(!macro_parameter_build_command("START_PRINT",values,1,command,8,&error) && !command[0]);\n values[0].name="BAD NAME";assert(!macro_parameter_build_command("START_PRINT",values,1,command,sizeof(command),&error));\n values[0].name="BED_TEMP";assert(macro_parameter_build_command("START_PRINT",values,0,command,sizeof(command),&error));\n assert(!strcmp(command,"START_PRINT"));\n return 0;\n}\n', 'endstop': '#include <assert.h>\n#include <string.h>\n#include "cJSON.h"\n#include "endstop_status_controller.h"\nstatic int64_t now;\nint64_t esp_timer_get_time(void) { return now; }\nstatic void reply(uint32_t id, uint32_t generation, const char *result, bool error) {\n cJSON *root=cJSON_CreateObject();cJSON_AddNumberToObject(root,"id",id);\n cJSON_AddItemToObject(root,error?"error":"result",cJSON_Parse(result));\n assert(endstop_status_controller_merge(root,generation));cJSON_Delete(root);\n}\nstatic endstop_status_snapshot_t get(void) { endstop_status_snapshot_t s;endstop_status_controller_snapshot(&s);return s; }\nint main(void) {\n endstop_status_controller_reset();assert(!get().valid && !get().waiting);\n uint32_t id=endstop_status_controller_begin(1);\n reply(id,2,"{\\"x\\":\\"TRIGGERED\\"}",false);assert(get().waiting && !get().valid);\n reply(id,1,"{\\"x\\":\\"TRIGGERED\\",\\"y\\":\\"open\\",\\"z\\":\\"open\\",\\"malformed\\":4}",false);\n assert(get().valid && get().count==3 && get().items[0].triggered && !get().items[1].triggered);\n id=endstop_status_controller_begin(1);now+=5000000;assert(!get().waiting && !get().valid && strstr(get().error,"timed out"));\n reply(id,1,"{\\"x\\":\\"open\\"}",false);assert(!get().valid);\n uint32_t next=endstop_status_controller_begin(1);reply(id,1,"{\\"x\\":\\"open\\"}",false);assert(get().waiting);\n reply(next,1,"{\\"message\\":\\"Printer is not ready\\"}",true);assert(!get().valid && strstr(get().error,"not ready"));\n id=endstop_status_controller_begin(2);endstop_status_controller_reset();reply(id,2,"{\\"x\\":\\"open\\"}",false);assert(!get().valid);\n id=endstop_status_controller_begin(2);reply(id,2,"{}",false);assert(get().valid && get().count==0);\n return 0;\n}\n', 'macro_catalog': '#include <assert.h>\n#include <string.h>\n#include "cJSON.h"\n#include "macro_controller.h"\nint main(void) {\n assert(macro_controller_init());\n cJSON *objects=cJSON_Parse("[\\"gcode_macro START_PRINT\\",\\"gcode_macro _HELPER\\",\\"gcode_macro PAUSE\\"]");\n macro_controller_update_from_objects(objects);cJSON_Delete(objects);\n macro_controller_status_t status;macro_controller_status(&status);assert(status.count==2);\n cJSON *config=cJSON_Parse("{\\"gcode_macro start_print\\":{\\"gcode\\":\\"params.BED_TEMP params.EXTRUDER_TEMP params.TOOL\\"}}");\n macro_controller_update_parameters(config);cJSON_Delete(config);\n macro_parameter_catalog_t parameters;\n assert(macro_controller_parameters("START_PRINT",&parameters) && parameters.count==3);\n assert(macro_controller_parameters("PAUSE",&parameters) && parameters.count==0);\n macro_controller_update_from_objects(NULL);\n assert(!macro_controller_parameters("START_PRINT",&parameters) && parameters.count==0);\n return 0;\n}\n', 'motion': '#include <assert.h>\n#include <math.h>\n#include <string.h>\n#include <stdio.h>\n#include "cJSON.h"\n#include "motion_diagnostics_controller.h"\nstatic uint32_t generation = 1;\nstatic motion_diagnostics_snapshot_t snapshot;\nuint32_t moonraker_config_generation(void){return generation;}\nstatic void status(const char *text) {\n cJSON *root=cJSON_Parse(text); assert(root);\n assert(motion_diagnostics_controller_merge_status(root));cJSON_Delete(root);\n motion_diagnostics_controller_snapshot(&snapshot);\n}\nint main(void){\n assert(motion_diagnostics_controller_init());\n cJSON *objects=cJSON_Parse("[\\"tmc2209 stepper_x\\",\\"tmc5160 stepper_z\\",\\"extruder\\"]");\n motion_diagnostics_controller_update_objects(objects);cJSON_Delete(objects);\n motion_diagnostics_controller_snapshot(&snapshot);assert(snapshot.driver_count==2 && snapshot.discovered);\n cJSON *config=cJSON_Parse("{\\"printer\\":{\\"kinematics\\":\\"cartesian\\"},\\"stepper_x\\":{\\"rotation_distance\\":\\"40\\"},\\"stepper_y\\":{\\"rotation_distance\\":40},\\"stepper_z\\":{\\"rotation_distance\\":\\"8\\"}}");\n motion_diagnostics_controller_update_config(config);cJSON_Delete(config);\n motion_diagnostics_controller_snapshot(&snapshot);assert(snapshot.rotation_valid[0] && snapshot.rotation_distance[0]==40 && snapshot.rotation_distance[2]==8);\n status("{\\"toolhead\\":{\\"max_velocity\\":250,\\"max_accel\\":2500,\\"square_corner_velocity\\":5,\\"minimum_cruise_ratio\\":0.5},\\"tmc2209 stepper_x\\":{\\"run_current\\":0.8,\\"hold_current\\":0.2,\\"temperature\\":null,\\"drv_status\\":null}}");\n assert(snapshot.limit_valid[3] && snapshot.limits[3]==0.5);\n assert(snapshot.drivers[0].run_valid && !snapshot.drivers[0].status_valid && !snapshot.drivers[0].temperature_valid && !snapshot.drivers[0].warning);\n status("{\\"toolhead\\":{\\"max_accel\\":1000},\\"tmc2209 stepper_x\\":{\\"drv_status\\":{\\"otpw\\":1}}}");\n assert(snapshot.limits[1]==1000 && snapshot.limits[0]==250);\n assert(snapshot.drivers[0].warning && !snapshot.drivers[0].fault && snapshot.drivers[0].status_valid && snapshot.drivers[0].run_current==0.8);\n status("{\\"tmc2209 stepper_x\\":{\\"drv_status\\":{\\"ot\\":1,\\"s2ga\\":1}}}");\n assert(snapshot.drivers[0].fault && strstr(snapshot.drivers[0].flags,"Short to ground A"));\n status("{\\"tmc2209 stepper_x\\":{\\"drv_status\\":{\\"stst\\":1,\\"cs_actual\\":16}},\\"tmc5160 stepper_z\\":{\\"temperature\\":73.5,\\"drv_status\\":{},\\"run_current\\":0.65,\\"hold_current\\":0.15}}");\n assert(!snapshot.drivers[0].warning && !snapshot.drivers[0].fault && snapshot.drivers[0].status_valid);\n assert(snapshot.drivers[1].temperature_valid && snapshot.drivers[1].temperature==73.5);\n status("{\\"tmc2209 stepper_x\\":{\\"drv_status\\":null,\\"run_current\\":null},\\"toolhead\\":{\\"minimum_cruise_ratio\\":null}}");\n assert(!snapshot.drivers[0].status_valid && !snapshot.drivers[0].run_valid && !snapshot.limit_valid[3]);\n status("{\\"tmc2209 stepper_x\\":{\\"run_current\\":-1},\\"toolhead\\":{\\"max_accel\\":0,\\"minimum_cruise_ratio\\":2}}");\n assert(!snapshot.drivers[0].run_valid && !snapshot.limit_valid[1] && !snapshot.limit_valid[3]);\n ++generation;motion_diagnostics_controller_snapshot(&snapshot);assert(!snapshot.driver_count && !snapshot.limit_valid[0]);\n status("{\\"toolhead\\":{\\"max_velocity\\":200}}");assert(snapshot.limit_valid[0] && snapshot.limits[0]==200 && !snapshot.driver_count);\n motion_diagnostics_controller_reset();motion_diagnostics_controller_snapshot(&snapshot);assert(!snapshot.limit_valid[0]);\n cJSON *many=cJSON_CreateArray();for(int i=0;i<14;++i){char name[80];snprintf(name,sizeof(name),"tmc2209 stepper_%d",i);cJSON_AddItemToArray(many,cJSON_CreateString(name));}\n motion_diagnostics_controller_update_objects(many);cJSON_Delete(many);motion_diagnostics_controller_snapshot(&snapshot);\n assert(snapshot.driver_count==12 && snapshot.drivers_truncated);\n double result;const char *error;\n assert(motion_axis_distance_calculate("2","20",&result,&error) && result==40);\n assert(motion_axis_distance_calculate("2","4",&result,&error) && result==8);\n assert(motion_axis_distance_calculate("1.25","1",&result,&error) && result==1.25);\n const char *invalid[]={"0","-2","nan","inf","2bad","1e999","0.000000001"};\n for(unsigned i=0;i<sizeof(invalid)/sizeof(*invalid);++i)assert(!motion_axis_distance_calculate(invalid[i],"20",&result,&error));\n assert(!motion_axis_distance_calculate("2","2.5",&result,&error));\n assert(!motion_axis_distance_calculate("2","0",&result,&error));\n assert(!motion_axis_distance_calculate("2","10001",&result,&error));\n assert(motion_axis_distance_calculate(" 2 ","20",&result,&error) && result==40);\n return 0;\n}\n'}
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--cjson-dir", type=Path)
parser.add_argument("--require-cjson", action="store_true", help="Fail instead of skipping JSON controller checks")
args = parser.parse_args()
candidates = [args.cjson_dir] if args.cjson_dir else []
candidates.append(Path(os.environ.get("PRINTERHMI_IDF6_PATH", "~/esp/esp-idf-v6.0.2")).expanduser() / "components/json/cJSON")
if os.environ.get("IDF_PATH"):
    candidates.append(Path(os.environ["IDF_PATH"]) / "components/json/cJSON")
if (ROOT / "managed_components").exists():
    candidates.extend(p.parent for p in (ROOT / "managed_components").rglob("cJSON.c"))
cjson = next((p for p in candidates if p and (p / "cJSON.h").exists() and (p / "cJSON.c").exists()), None)
if args.require_cjson and cjson is None:
    parser.error("cJSON sources are required; supply --cjson-dir or build managed components first")
with tempfile.TemporaryDirectory(prefix="tools-features-") as directory:
    tmp = Path(directory)
    for name, contents in STUBS.items():
        path = tmp / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(contents)
    for name, contents in TESTS.items():
        if name != "parameter" and cjson is None:
            print(f"SKIP: {name} (supply --cjson-dir for JSON controller checks)")
            continue
        path = tmp / (name + ".c")
        path.write_text(contents)
        sources = [ROOT / "main" / {"parameter": "macro_parameter_utils.c",
                                   "endstop": "endstop_status_controller.c",
                                   "macro_catalog": "macro_parameter_utils.c",
                                   "motion": "motion_diagnostics_controller.c"}[name]]
        if name == "macro_catalog":
            sources.append(ROOT / "main/macro_controller.c")
        flags = []
        if name != "parameter":
            sources.append(cjson / "cJSON.c")
            flags += ["-I", str(cjson)]
        executable = tmp / name
        subprocess.run(["cc", "-std=c11", "-Wall", "-Wextra", "-Werror",
                        "-I", str(tmp), "-I", str(ROOT / "main"), *flags,
                        *map(str, sources), str(path), "-lm", "-o", str(executable)], check=True)
        subprocess.run([str(executable)], check=True)
        print(f"PASS: {name}")
